from pathlib import Path
p=Path('/mnt/data/oreone-website')
nav=[('Home','index.html'),('About','about.html'),('What We Do','what-we-do.html'),('Who We Serve','who-we-serve.html'),('Partnerships','partnerships.html'),('Insights','insights.html'),('Contact','contact.html')]
def header(active):
    links=''.join(f'<a href="{href}" {"aria-current=page" if label==active else ""}>{label}</a>' for label,href in nav)
    return f'''<a class="skip-link" href="#main">Skip to content</a><header class="site-header"><div class="container nav-wrap"><a class="brand" href="index.html" aria-label="Oreone home"><span class="brand-mark" aria-hidden="true"></span><span>oreone</span></a><button class="menu-toggle" aria-expanded="false" aria-label="Toggle navigation">☰</button><nav class="nav-links" aria-label="Main navigation">{links}</nav><a class="btn nav-cta" href="contact.html">Partner With Us <span aria-hidden="true">→</span></a></div></header>'''
def footer():
    links=''.join(f'<a href="{href}">{label}</a>' for label,href in nav)
    return f'''<section class="cta-band"><div class="container cta-inner"><div><p class="eyebrow">Let's build together</p><h2>Have a challenge worth exploring?</h2><p>Whether you're a business, institution or development partner, Oreone can help turn your goals into practical outcomes.</p></div><a class="btn" href="contact.html">Talk to Oreone <span aria-hidden="true">→</span></a></div></section><footer class="site-footer"><div class="container"><div class="footer-top"><div><a class="brand" href="index.html"><span class="brand-mark" aria-hidden="true"></span><span>oreone</span></a><div class="footer-tagline">Development. Transformation. Opportunity.</div></div><nav class="footer-links" aria-label="Footer navigation">{links}</nav></div><div class="footer-bottom"><span>© <span data-year></span> Oreone International Limited. All rights reserved.</span><span><a href="contact.html">Contact</a> &nbsp;·&nbsp; <a href="privacy.html">Privacy notice</a></span></div></div></footer><script src="script.js" defer></script>'''
def page(title,description,active,body):
    return f'''<!doctype html><html lang="en-NG"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{title}</title><meta name="description" content="{description}"><meta name="robots" content="index,follow"><meta property="og:type" content="website"><meta property="og:site_name" content="Oreone International Limited"><meta property="og:title" content="{title}"><meta property="og:description" content="{description}"><meta name="theme-color" content="#07985d"><link rel="canonical" href="https://oreone.com/{'' if active=='Home' else (active.lower().replace(' ','-')+'.html' if active else 'privacy.html')}"><link rel="stylesheet" href="styles.css"><script type="application/ld+json">{{"@context":"https://schema.org","@type":"Organization","name":"Oreone International Limited","url":"https://oreone.com/","telephone":"+2348024945647","email":"support.oreoneinc@gmail.com","address":{{"@type":"PostalAddress","streetAddress":"No. 4 Daola Close, Monrovia Street, Wuse 2","addressLocality":"Abuja","addressCountry":"NG"}}}}</script></head><body>{header(active)}<main id="main">{body}</main>{footer()}</body></html>'''

def cards(items,cols=3):
    normalized=[tuple(item)+(('',)*(4-len(item))) for item in items]
    return f'<div class="grid grid-{cols}">'+''.join(f'<article class="card"><div class="icon-bubble" aria-hidden="true">{icon}</div><h3>{title}</h3><p>{desc}</p>{link}</article>' for icon,title,desc,link in normalized)+'</div>'

home='''<section class="hero"><div class="container hero-inner"><p class="eyebrow">Oreone International Limited</p><h1>Building better businesses. Strengthening institutions. Creating opportunity.</h1><p>Oreone works across the private, public and development sectors to strengthen enterprises, improve systems and turn opportunities into sustainable outcomes.</p><div class="hero-actions"><a class="btn" href="what-we-do.html">Explore What We Do →</a><a class="btn btn-outline" href="contact.html">Work With Oreone</a></div><div class="hero-note">Development &nbsp;•&nbsp; Business Transformation &nbsp;•&nbsp; Investment &nbsp;•&nbsp; Technology</div></div></section>
<section class="section"><div class="container"><div class="section-head"><div><p class="eyebrow">What we do</p><h2>Practical solutions for real-world challenges.</h2><p>We bring together business expertise, development knowledge, stakeholder engagement, research and technology to help turn ideas into measurable progress.</p></div><a class="btn btn-outline" href="what-we-do.html">View all capabilities →</a></div>'''+cards([('↗','Enterprise & MSME Development','Support for stronger, more resilient businesses and enterprise ecosystems.','<a class="card-link" href="what-we-do.html">Explore capability →</a>'),('◎','Access to Finance & Investment','Helping improve finance readiness, financial access and investment connections.','<a class="card-link" href="what-we-do.html">Explore capability →</a>'),('▦','Public Sector & Institutions','Practical support for institutional strengthening, policy and service delivery.','<a class="card-link" href="what-we-do.html">Explore capability →</a>'),('⌁','Programme Implementation','Programme design, coordination, stakeholder engagement and delivery support.','<a class="card-link" href="what-we-do.html">Explore capability →</a>'),('⌕','Research, Data & M&E','Evidence, learning and analysis to support stronger decisions.','<a class="card-link" href="what-we-do.html">Explore capability →</a>'),('◇','Digital Transformation','Technology and data tools that improve access, efficiency and transparency.','<a class="card-link" href="what-we-do.html">Explore capability →</a>')],3)+'''</div></section>
<section class="section section-soft"><div class="container split"><div><p class="eyebrow">How we work</p><h2>We bridge strategy and implementation.</h2><p class="section-intro">Good ideas matter when they respond to real needs and can be put into practice. We work collaboratively from problem definition through delivery, measurement and learning.</p><ul class="list-check"><li>Understand the context and the people affected</li><li>Design practical, locally relevant responses</li><li>Bring the right stakeholders and expertise together</li><li>Measure progress, learn and adapt</li></ul><a class="btn" href="partnerships.html">Explore Partnerships →</a></div><div class="photo-panel" role="img" aria-label="Professionals collaborating around a table"></div></div></section>
<section class="section"><div class="container"><div class="section-head"><div><p class="eyebrow">Who we serve</p><h2>Working across the development ecosystem.</h2><p>We collaborate with organisations and communities that want to solve practical problems and create lasting value.</p></div><a class="btn btn-outline" href="who-we-serve.html">Who We Serve →</a></div>'''+cards([('▤','Development Partners','Technical assistance, research, programme delivery and learning.' ,''),('⌂','Public Institutions','Institutional support, policy engagement and implementation.' ,''),('↗','Businesses & Financial Institutions','Enterprise support, market development and financial access.' ,''),('♧','Communities & Ecosystems','Stakeholder coordination and locally grounded economic development.' ,'')],4)+'''</div></section>'''
(p/'index.html').write_text(page('Oreone International | Development & Business Transformation in Nigeria','Oreone International is a development and business transformation company working with businesses, public institutions and development partners in Nigeria.','Home',home))

about='''<section class="page-title"><div class="container"><div class="crumb">Home / About</div><p class="eyebrow">About Oreone</p><h1>Development solutions for a changing Africa.</h1><p>We work with businesses, institutions and development partners to solve practical problems, strengthen systems and create sustainable opportunities.</p></div></section><section class="section"><div class="container split"><div><p class="eyebrow">Who we are</p><h2>Focused on the problem. Committed to practical outcomes.</h2><p class="section-intro">Oreone International Limited is a development and business transformation organisation. We bring together business understanding, development practice, research, partnerships and technology where these capabilities can improve outcomes.</p><p class="section-intro" style="margin-top:14px">Our work connects enterprise growth with institutional effectiveness and the wider economic systems that shape opportunity.</p></div><div class="photo-panel" role="img" aria-label="Professionals working together"></div></div></section><section class="section section-soft"><div class="container grid grid-2"><article><p class="eyebrow">Our mission</p><h2>Turn important challenges into practical solutions.</h2><p class="section-intro">We identify real needs, build relevant responses and work with partners to deliver, learn and improve.</p></article><article><p class="eyebrow">Our vision</p><h2>More opportunity. Stronger systems. Sustainable progress.</h2><p class="section-intro">We want to contribute to productive businesses, capable institutions and economic ecosystems where people and organisations can thrive.</p></article></div></section><section class="section"><div class="container"><div class="section-head"><div><p class="eyebrow">How we think</p><h2>Principles that guide our work.</h2></div></div>'''+cards([('◎','Problem first','Start with the real challenge, not a predetermined solution.',''),('✦','Practical innovation','Choose approaches that people can use and sustain.',''),('◇','Integrity','Be clear about evidence, commitments and limitations.',''),('↗','Partnership','Work collaboratively and respect local knowledge.','')],4)+'''</div></section>'''
(p/'about.html').write_text(page('About Oreone | Development Consulting Nigeria','Learn about Oreone International Limited, a development and business transformation organisation working across Nigeria’s private, public and development sectors.','About',about))

services=[('↗','Enterprise & MSME Development','MSME diagnostics, business capacity building, formalisation support, investment readiness, market development and enterprise support programmes.'),('◎','Access to Finance & Investment','Finance-readiness support, financial product mapping, access-to-finance initiatives, investment facilitation and business-finance matchmaking.'),('▦','Public Sector & Institutional Strengthening','Institutional assessments, strategy and process improvement, policy support, stakeholder engagement and public-private dialogue.'),('⚙','Development Programme Implementation','Programme design, coordination, technical assistance, stakeholder mobilisation, capacity building and delivery support.'),('⌕','Research, Data & Monitoring & Evaluation','Market research, rapid assessments, surveys, interviews, data analysis, monitoring, evaluation, learning and reporting.'),('◇','Digital Transformation & Technology','Digital tools, workflow improvement, business management systems, platform development and technology-enabled service delivery.')]
what='<section class="page-title"><div class="container"><div class="crumb">Home / What We Do</div><p class="eyebrow">Our capabilities</p><h1>Turning challenges into practical solutions.</h1><p>Oreone works across the private, public and development sectors to strengthen businesses, institutions and economic ecosystems.</p></div></section><section class="section"><div class="container">'+cards([(a,b,c,'') for a,b,c in services],3)+'</div></section><section class="section section-soft"><div class="container"><div class="section-head"><div><p class="eyebrow">Our approach</p><h2>From insight to measurable outcomes.</h2><p>Our approach is collaborative, practical and designed to adapt as we learn.</p></div></div><div class="steps">'+''.join(f'<div class="step"><b>0{i+1}</b><h3>{t}</h3><p>{d}</p></div>' for i,(t,d) in enumerate([('Understand','Analyse the context, needs and priorities.'),('Design','Develop practical strategies and solutions.'),('Mobilise','Bring partners, people and resources together.'),('Implement','Support delivery and coordination.'),('Measure','Track progress and learn from evidence.')]))+'</div></div></section>'
(p/'what-we-do.html').write_text(page('What We Do | Development Consulting & Technical Assistance | Oreone','Explore Oreone’s services in MSME development, access to finance, institutional strengthening, programme implementation, research and monitoring and evaluation in Nigeria.','What We Do',what))

who='<section class="page-title"><div class="container"><div class="crumb">Home / Who We Serve</div><p class="eyebrow">Who we serve</p><h1>Working across the development ecosystem.</h1><p>We work with businesses, government institutions, development organisations and economic ecosystems to solve practical problems, strengthen capacity and create sustainable opportunities.</p></div></section><section class="section"><div class="container">'+cards([('↗','Private Sector','SMEs and entrepreneurs, corporates, financial institutions and investors.'),('▦','Public Sector','Ministries, departments and agencies, state and local governments, and public institutions.'),('♧','Development Partners','Donors, NGOs, development organisations and implementing partners.'),('⌂','Communities & Economic Ecosystems','Cooperatives, business clusters, industry associations and local economic ecosystems.')],4)+'</div></section><section class="section section-soft"><div class="container split"><div><p class="eyebrow">A connected perspective</p><h2>Connecting business, finance, government and development.</h2><p class="section-intro">Many challenges cross organisational boundaries. We help partners understand the wider system, coordinate stakeholders and connect strategy with implementation.</p></div><div class="card"><h3>Oreone as connector and implementer</h3><div class="pill-row"><span class="pill">Business</span><span class="pill">Finance</span><span class="pill">Government</span><span class="pill">Development</span><span class="pill">Communities</span><span class="pill">Technology</span></div></div></div></section><section class="section"><div class="container"><p class="eyebrow">Frequently asked questions</p><h2>Who does Oreone work with?</h2><div class="faq-list"><details><summary>What sectors does Oreone work with in Nigeria?</summary><p>Oreone works across private-sector enterprise, public institutions, development programmes, financial services and economic ecosystems.</p></details><details><summary>Does Oreone support SMEs and MSMEs?</summary><p>Yes. Oreone’s capability areas include enterprise development, business support, investment readiness, market development and access-to-finance initiatives.</p></details><details><summary>Can development partners engage Oreone for programme implementation?</summary><p>Potential partners can contact Oreone to discuss programme needs, scope, relevant experience and appropriate engagement arrangements.</p></details><details><summary>Does Oreone provide research and monitoring and evaluation?</summary><p>Research, assessments, data analysis, monitoring, evaluation and learning are among Oreone’s service areas.</p></details></div></div></section>'
(p/'who-we-serve.html').write_text(page('Who We Serve | Development Partners, Public & Private Sector | Oreone','Oreone works with development partners, government institutions, SMEs, financial institutions and communities on development and business transformation in Nigeria.','Who We Serve',who))

partnerships='<section class="hero"><div class="container hero-inner"><p class="eyebrow">Partnerships</p><h1>The right partner for the right challenge.</h1><p>Oreone works with development partners, public institutions, businesses and economic organisations to design and deliver practical solutions that create measurable and sustainable outcomes.</p><div class="hero-actions"><a class="btn" href="contact.html">Partner With Us →</a><a class="btn btn-outline" href="#models">Our Partnership Models</a></div></div></section><section class="section" id="models"><div class="container"><div class="section-head"><div><p class="eyebrow">Partnership models</p><h2>Flexible models. Lasting impact.</h2><p>We shape engagements to fit partner goals, operating context and programme needs.</p></div></div>'+cards([('♧','Lead Consultant','Strategic and technical leadership for programmes and initiatives.'),('⚙','Technical Partner','Specialist expertise to strengthen project design and delivery.'),('▣','Implementation Partner','On-the-ground execution, coordination and programme management.'),('⌕','Research & M&E Partner','Research, assessments, monitoring, evaluation and learning.'),('♧','Capacity-Building Partner','Skills and institutional capacity for long-term sustainability.'),('⌁','Ecosystem Coordinator','Stakeholder coordination and collaboration across the value chain.')],3)+'</div></section><section class="section section-soft"><div class="container"><div class="section-head"><div><p class="eyebrow">Working with different partners</p><h2>Different partners. Shared goals.</h2></div></div>'+cards([('♧','For Development Partners','MSME development, access to finance, enterprise support, institutional strengthening, research, programme implementation, M&E and stakeholder engagement.'),('▦','For Government & Public Institutions','Policy and programme support, institutional strengthening, public-private dialogue, business environment improvement, data and implementation support.'),('↗','For Private Sector & Financial Institutions','Enterprise development, market intelligence, finance initiatives, digital transformation and business ecosystem development.')],3)+'</div></section><section class="section section-dark"><div class="container"><p class="eyebrow">Our approach</p><h2>From insight to measurable outcomes.</h2><div class="steps">'+''.join(f'<div class="step"><b>0{i+1}</b><h3>{t}</h3><p>{d}</p></div>' for i,(t,d) in enumerate([('Understand','Clarify the challenge, context and priorities.'),('Design','Develop a practical response.'),('Mobilise','Bring partners and expertise together.'),('Implement','Deliver with coordination and focus.'),('Measure','Track progress, learn and adapt.')]))+'</div></div></section><section class="section"><div class="container"><p class="eyebrow">Frequently asked questions</p><h2>Working with Oreone</h2><div class="faq-list"><details><summary>Can Oreone work as a technical or implementation partner?</summary><p>Oreone welcomes discussions about technical assistance, implementation, research, capacity building and ecosystem coordination. Each engagement depends on scope and fit.</p></details><details><summary>Does Oreone work with development partners in Nigeria?</summary><p>Oreone is positioned to engage with development organisations and implementing partners on relevant assignments. Contact us to discuss your needs and procurement requirements.</p></details><details><summary>How do we start a partnership discussion?</summary><p>Send an enquiry through the contact form with your organisation, goals, timelines and the kind of support you need.</p></details></div></div></section>'
(p/'partnerships.html').write_text(page('Partnerships | Development Consulting & Programme Delivery | Oreone','Explore partnership models with Oreone International for development programmes, technical assistance, research, institutional strengthening and enterprise support in Nigeria.','Partnerships',partnerships))

insights='<section class="hero"><div class="container hero-inner"><p class="eyebrow">Insights</p><h1>Ideas, evidence and perspectives for a changing economy.</h1><p>Practical insights on business, development, finance, institutions and technology—grounded in the realities of Nigeria and the wider African economy.</p><div class="hero-actions"><a class="btn" href="#topics">Explore Topics →</a><a class="btn btn-outline" href="contact.html">Work With Oreone</a></div></div></section><section class="section"><div class="container"><div class="section-head"><div><p class="eyebrow">Featured insights</p><h2>In-depth analysis for real-world impact.</h2><p>Editorial topics we plan to develop through practical analysis, original research and clearly attributed evidence.</p></div></div><div class="grid grid-3">'+''.join(f'<article class="card article-card"><div class="article-image">{tag}</div><div class="article-body"><span class="tag">{category}</span><h3>{title}</h3><p>{desc}</p><div class="article-meta">Editorial topic · Article forthcoming</div></div></article>' for tag,category,title,desc in [('MSME & enterprise','MSME Development','What It Takes to Make MSME Finance Work in Nigeria','Exploring practical ways to bridge financing gaps and support enterprise resilience.'),('Finance & investment','Access to Finance','From Access to Finance to Finance Readiness','Why finance availability must be matched with business readiness and suitable products.'),('Programme delivery','Development Programmes','Why Implementation Matters in Development Programmes','Lessons on translating strategies into delivery, learning and outcomes.')])+'</div><p class="notice">These are planned editorial topics, not published articles or claims of completed research. We will add article pages as the content is developed and verified.</p></div></section><section class="section section-soft" id="topics"><div class="container split"><div><p class="eyebrow">Explore by topic</p><h2>Find what matters to you.</h2><p class="section-intro">The Insights library will organise practical analysis and explainers across Oreone’s areas of interest.</p></div><div class="topic-list">'+''.join(f'<a href="contact.html?topic={t.replace(" ","%20")}">{t}</a>' for t in ['MSME & Enterprise Development','Access to Finance & Investment','Public Sector & Institutions','Development Programmes','Research, Data & M&E','Digital Transformation','Business Environment','Africa & Economic Development'])+'</div></div></section><section class="section"><div class="container split"><div><p class="eyebrow">Research & evidence</p><h2>Better evidence. Better decisions.</h2><p class="section-intro">We intend to share research summaries, market assessments, survey findings, programme learning notes and policy explainers where the underlying evidence is available and can be responsibly attributed.</p></div><div class="card"><h3>What to expect</h3><ul class="list-check"><li>Research and assessment summaries</li><li>Practical guides and explainers</li><li>Programme learning and case studies</li><li>Policy and market perspectives</li><li>Evidence-based recommendations</li></ul></div></div></section>'
(p/'insights.html').write_text(page('Insights | Business, Development & Finance in Nigeria | Oreone','Practical perspectives on MSME development, access to finance, institutions, programme implementation, research and digital transformation in Nigeria.','Insights',insights))

contact='<section class="hero"><div class="container hero-inner"><p class="eyebrow">Contact Oreone</p><h1>Let’s solve the right problem.</h1><p>Whether you’re a development partner, government institution, business or organisation seeking support, we’d love to hear from you. Tell us about your goals and how we can work together.</p><div class="pill-row"><span class="pill" style="color:white;border-color:#7aa99a">Responsive</span><span class="pill" style="color:white;border-color:#7aa99a">Collaborative</span><span class="pill" style="color:white;border-color:#7aa99a">Impact-driven</span></div></div></section><section class="section"><div class="container contact-grid"><div><p class="eyebrow">Get in touch</p><h2>How can we help you?</h2><p class="section-intro">Select the option that best describes your interest. For general enquiries, use the form.</p><div class="contact-options" style="margin-top:22px">'+''.join(f'<a class="option" href="contact.html?topic={title.replace(chr(32),"%20")}" ><div class="icon-bubble">{icon}</div><div><strong>{title}</strong><span>{desc}</span></div></a>' for icon,title,desc in [('♧','Development Partnership','Collaborate on development goals.'),('♙','Consulting / Advisory','Strategic advice and technical support.'),('⚙','Programme Implementation','Turn plans into measurable outcomes.'),('⌕','Research & M&E','Evidence, learning and better decisions.'),('▦','Enterprise / MSME Support','Stronger businesses and opportunities.'),('◎','Investment & Access to Finance','Finance readiness and investment links.'),('◇','Digital Transformation','Technology for greater efficiency.'),('✉','General Enquiry','Other questions or information.')])+'</div><div style="margin-top:30px"><p class="eyebrow">Contact details</p><div class="contact-detail"><div class="icon-bubble">⌖</div><div><h3>Office address</h3><p>No. 4 Daola Close, Monrovia Street,<br>Wuse 2, Abuja, Nigeria</p></div></div><div class="contact-detail"><div class="icon-bubble">☎</div><div><h3>Telephone</h3><p><a href="tel:+2348024945647">08024945647</a></p></div></div><div class="contact-detail"><div class="icon-bubble">✉</div><div><h3>Email</h3><p><a href="mailto:support.oreoneinc@gmail.com">support.oreoneinc@gmail.com</a></p></div></div></div></div><div class="form-card"><p class="eyebrow">Send us a message</p><h2 style="font-size:30px">Get in touch</h2><p class="section-intro" style="font-size:14px;margin-bottom:20px">Complete the form and your email application will open with your enquiry prepared.</p><form id="contact-form"><div class="form-grid"><div class="field"><label for="name">Full name *</label><input id="name" name="name" autocomplete="name" required></div><div class="field"><label for="email">Email address *</label><input id="email" name="email" type="email" autocomplete="email" required></div><div class="field"><label for="organisation">Organisation</label><input id="organisation" name="organisation" autocomplete="organization"></div><div class="field"><label for="phone">Phone number</label><input id="phone" name="phone" type="tel" autocomplete="tel"></div><div class="field full"><label for="enquiry">How can we help you? *</label><select id="enquiry" name="enquiry" required><option value="">Select an option</option><option>Development Partnership</option><option>Consulting / Advisory</option><option>Programme Implementation</option><option>Research & M&E</option><option>Enterprise / MSME Support</option><option>Investment & Access to Finance</option><option>Digital Transformation</option><option>General Enquiry</option></select></div><div class="field full"><label for="message">Message *</label><textarea id="message" name="message" placeholder="Tell us about your enquiry, goals and timelines..." required></textarea></div><div class="field full"><button class="btn" type="submit">Prepare email enquiry →</button><p id="form-status" class="notice" aria-live="polite">This first version uses your email app to send the message; it does not store form submissions.</p></div></div></form></div></div></section><section class="section section-soft"><div class="container split"><div><p class="eyebrow">Find our office</p><h2>Visit Oreone in Abuja.</h2><p class="section-intro">No. 4 Daola Close, Monrovia Street, Wuse 2, Abuja, Nigeria.</p><p style="margin-top:18px"><a class="btn btn-outline" href="https://www.google.com/maps/search/?api=1&query=No%204%20Daola%20Close%2C%20Monrovia%20Street%2C%20Wuse%202%2C%20Abuja%2C%20Nigeria" target="_blank" rel="noopener">Open directions in Google Maps →</a></p></div><iframe class="map-panel" title="Map search for the Oreone Abuja office" loading="lazy" src="https://maps.google.com/maps?q=Wuse%202%2C%20Abuja%2C%20Nigeria&t=&z=13&ie=UTF8&iwloc=&output=embed"></iframe></div></section>'
(p/'contact.html').write_text(page('Contact Oreone International | Development & Consulting Nigeria','Contact Oreone International to discuss development partnerships, consulting, MSME support, programme implementation, research, institutional strengthening and digital transformation in Nigeria.','Contact',contact))

privacy='<section class="page-title"><div class="container"><div class="crumb">Home / Privacy notice</div><p class="eyebrow">Privacy</p><h1>Privacy notice</h1><p>A simple starter privacy notice for the Oreone website.</p></div></section><section class="section"><div class="container" style="max-width:800px"><h2>Information you provide</h2><p>When you use the contact form, the details you enter are placed into an email draft on your device. This static starter website does not store form submissions on a server.</p><h2>Contact</h2><p>For privacy-related questions, email <a href="mailto:support.oreoneinc@gmail.com">support.oreoneinc@gmail.com</a>.</p><p class="notice">Before launch, have this notice reviewed and expanded to reflect the final hosting, analytics, form provider, retention practices and applicable legal requirements.</p></div></section>'
